from __future__ import absolute_import
from builtins import str, range
import re
import time
import paramiko
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable, get_config_variable_from_string
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.remote_command_execute_and_verify import ExecuteAndVerify
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()

MAX_CONN_RETRIES = 6
MAX_RETRIES = 60


class SshConnection(ExecuteAndVerify):
    """
    Contains the methods which are used to connect switch via ssh connection
    """

    def __init__(self, device, command_profile):
        """
        This function initializes the variables when the object of sshconnection class is created.
        Args:
            device: Name of the device section taken from testline config file in fw_path/
            command_profile: Command profile name which will be inside switch section of testline config file

        Returns:

        """
        self.ssh = paramiko.SSHClient()
        self.ssh_shell = None
        self.ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self.ip = get_config_variable(['switch', device, "ip"])
        self.user = get_config_variable(['switch', device, "user"])
        self.password = get_config_variable(['switch', device, "password"])
        self.enable_password = get_config_variable(["switch", device, "enable_password"])
        self.command_profile = get_config_variable_from_string(["switch", device, "command_profiles", command_profile])
        # self.command_profile = get_config_variable(["switch", device, "command_profiles", command_profile])
        self.enable_prompt = get_config_variable(["switch", device, "enable_prompt"])
        # self.enable_prompt = self.enable_prompt
        logger.info(self.command_profile)
        self.verification_timeout = get_config_variable(["switch", device, "verification_timeout"])
        self.error_messages = ["% Invalid input detected at '^' marker.", "% Incomplete command.",
                               "% Ambiguous command:",
                               "% Unknown command or computer name, or unable to find computer address"]
        self.show_command = "show conf"

    def login_to_switch(self):
        """
        Logs in to the switch using connect command of the paramiko lib, by taking appropriate credentials from
        config variable. If the command fails with bad host key exception, it adds the missing host key policy.
        If the connection fails with any other exception it throws appropriate exception and terminates.
        Returns:

        """
        logger.debug("username:{} password:{}".format(self.user, self.password))
        for i in range(MAX_CONN_RETRIES):
            try:
                self.ssh.connect(self.ip, username=self.user, password=self.password, look_for_keys=False,
                                 banner_timeout=60)
                break
            except paramiko.BadHostKeyException as e:
                logger.debug("INFO: {}".format(e))
                self.ssh.get_host_keys().clear()
                self.ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                self.ssh.connect(self.ip, username=self.user, password=self.password, look_for_keys=False,
                                 banner_timeout=60)
                break
            except paramiko.SSHException as e:
                logger.warn("SSH exception: going for retry " + str(e))
                time.sleep(2)
                if i == 5:
                    self.ssh.close()
                    self.ssh = None
                    BuiltIn().fail("SSH to " + self.ip + " failed after 5 retries with error :: " + str(e))
            except Exception as e:
                logger.warn("Retry :: Failed to create SSH session due to {0}".format(e))
                if i == 5:
                    raise Exception("SSH Failed due to error ::" + str(e))
        self.ssh_shell = self.ssh.invoke_shell()

        output = decode_str(self.ssh_shell.recv(65535))
        if bool(re.search(".*>$", output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
            self._perform_en_login()
        else:
            logger.info("Either enable password is missing in config file, or enable login is not required")
        logger.info("SSH connection successful !!{0}".format(self.ssh))

    def _perform_en_login(self):
        """
        This login is required to enter the "en" mode of the switch, it uses
        send and recv methods of the paramiko lib
        to execute "en" command.
            Returns:

        """
        self._execute_cmd("en", expected_prompt='Password', retries=1)
        self._execute_cmd(self.enable_password, expected_prompt=self.enable_prompt, retries=MAX_RETRIES)
        self._set_terminal_length()

    def _execute_cmd(self, command, **kwargs):
        expected_prompt = kwargs.get('expected_prompt', self.enable_prompt) or '#'
        retries = kwargs.get('retires') or MAX_RETRIES
        self.ssh_shell.send("{}\n".format(command))
        for i in range(retries):
            logger.debug("waiting for prompt {}".format(expected_prompt))
            time.sleep(1)
            output = decode_str(self.ssh_shell.recv(65535))
            if bool(re.search(expected_prompt, output, re.MULTILINE | re.DOTALL | re.IGNORECASE)):
                logger.debug("Command Output : {}".format(output))
                return output
        BuiltIn().fail("Command execution failed as expected prompt did not appear in output")

    def _set_terminal_length(self):
        """
        Setting the terminal length to 0, so that all the output of the screen are dumped at once without user
        intervention.
        Returns:

        """
        self._execute_cmd("terminal length 0", expected_prompt=self.enable_prompt, retries=1)

    def close_connection(self):
        """
        Logs out of the switch using close function of paramiko library.
        Returns:
        """
        self.ssh.close()
        logger.info("SSH connection closed successfully")
        return

    def configure_switch(self, **kwargs):
        """
        Configure switch is used to manage the switch operations.
        It does following operations:
        1. Login To switch
        2. Execute various commands based on the command profiles present in the switch section of the testline config
        3. Logs out of the switch
         Args:
        max_retries: max number of retries to be done
        Returns:

        """
        logger.info("Configuring Switch via ssh..")
        try:
            self.login_to_switch()
            self.execute_commands_and_verify()
        except Exception as e:
            raise e
        finally:
            self.close_connection()
